# test generated by chatgpt

from unittest.mock import patch

import pymupdf as fitz

from lexicore.agents.parser_agent import parse_document


def create_pdf(tmp_path):

    file_path = tmp_path / "simple.pdf"

    pdf = fitz.open()

    page = pdf.new_page()

    page.insert_text(
        (50, 50),
        "This is a simple PDF document.",
    )

    pdf.save(file_path)
    pdf.close()

    return file_path


@patch(
    "lexicore.agents.parser_agent.parse_with_unstructured"
)
@patch(
    "lexicore.agents.parser_agent.parse_with_ocr"
)
@patch(
    "lexicore.agents.parser_agent.parse_with_pymupdf"
)
def test_simple_pdf_routes_to_pymupdf(
    mock_pymupdf,
    mock_ocr,
    mock_unstructured,
    tmp_path,
):

    file_path = create_pdf(tmp_path)

    mock_pymupdf.return_value = {
        "page_number": 1,
        "column_count": 1,
        "blocks": [],
    }

    result = parse_document(file_path)

    mock_pymupdf.assert_called_once()

    mock_ocr.assert_not_called()

    mock_unstructured.assert_not_called()

    assert result["pages"][0]["parser"] == "pymupdf"





@patch(
    "lexicore.agents.parser_agent.parse_with_unstructured"
)
@patch(
    "lexicore.agents.parser_agent.parse_with_pymupdf"
)
@patch(
    "lexicore.agents.parser_agent.parse_with_ocr"
)
def test_scanned_pdf_routes_to_ocr(
    mock_ocr,
    mock_pymupdf,
    mock_unstructured,
    tmp_path,
):

    file_path = tmp_path / "scanned.pdf"

    pdf = fitz.open()

    pdf.new_page()

    pdf.save(file_path)
    pdf.close()

    mock_ocr.return_value = {
        "elements": [],
    }

    result = parse_document(file_path)

    mock_ocr.assert_called_once()

    mock_pymupdf.assert_not_called()

    mock_unstructured.assert_not_called()

    assert result["pages"][0]["parser"] == "ocr"


@patch(
    "lexicore.agents.parser_agent.parse_with_ocr"
)
@patch(
    "lexicore.agents.parser_agent.parse_with_pymupdf"
)
@patch(
    "lexicore.agents.parser_agent.parse_with_unstructured"
)
def test_multi_column_pdf_routes_to_unstructured(
    mock_unstructured,
    mock_pymupdf,
    mock_ocr,
    tmp_path,
):

    file_path = tmp_path / "multi_column.pdf"

    pdf = fitz.open()

    page = pdf.new_page()

    page.insert_textbox(
        (50, 50, 250, 700),
        "This is the first column. " * 50,
    )

    page.insert_textbox(
        (300, 50, 500, 700),
        "This is the second column. " * 50,
    )

    pdf.save(file_path)
    pdf.close()

    mock_unstructured.return_value = {
        "tables": [],
        "texts": [],
    }

    result = parse_document(file_path)

    mock_unstructured.assert_called_once()

    mock_pymupdf.assert_not_called()

    mock_ocr.assert_not_called()

    assert result["pages"][0]["parser"] == "unstructured"